/* EMS Supershop Retail Console — native JS, server-backed, aggregate stock. */
const $=s=>document.querySelector(s);
const esc=(ctx,x)=>ctx.esc(x??'');
const rawEscape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(ctx,x)=>`৳ ${ctx.money(Number(x||0))}`;
const dateYmd=(date=new Date())=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const fmtDate=x=>x?new Date(String(x).slice(0,10)+'T00:00:00').toLocaleDateString('en-BD',{day:'2-digit',month:'short',year:'numeric'}):'—';
const n=(x,d=0)=>Number.isFinite(Number(x))?Number(x):d;
const r2=x=>Math.round((n(x)+Number.EPSILON)*100)/100;
const r3=x=>Math.round((n(x)+Number.EPSILON)*1000)/1000;
const uid=()=>crypto.randomUUID();
const icon=(ctx,name)=>ctx.lucide?ctx.lucide(name):'✦';
const button=(ctx,label,action,kind='soft',attrs='')=>`<button type="button" class="ss-btn ${kind==='primary'?'ss-btn-primary':''} ${kind==='danger'?'ss-btn-danger':''}" data-ss-action="${rawEscape(action||'')}" ${attrs}>${label}</button>`;
const pageActions=actions=>actions?`<div class="ss-page-actions"><div class="ss-toolbar-actions">${actions}</div></div>`:'';
const panel=(title,copy,body,actions='')=>`<section class="ss-panel"><header class="ss-panel-head"><div><span class="ss-eyebrow">SUPERSHOP</span><h2>${title}</h2>${copy?`<p>${copy}</p>`:''}</div>${actions?`<div class="ss-panel-actions">${actions}</div>`:''}</header>${body}</section>`;
const kpi=(ctx,ico,label,value,foot,tone='blue')=>`<article class="ss-kpi ss-kpi-${tone}"><span class="ss-kpi-icon">${icon(ctx,ico)}</span><div><small>${label}</small><b>${value}</b><span>${foot||''}</span></div></article>`;
const status=(label,tone='neutral')=>`<span class="ss-status ss-status-${['neutral','good','warning','bad','violet','blue','amber'].includes(tone)?tone:'neutral'}">${rawEscape(label)}</span>`;
const empty=message=>`<div class="ss-empty"><span>◌</span><b>${message}</b></div>`;
const table=(headers,rows,message='No records found.')=>rows.length?`<div class="ss-table-scroll"><table class="ss-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty(message);
const okCurrent=ctx=>!ctx.isCurrent||ctx.isCurrent();
function page(ctx,html){if(okCurrent(ctx)&&$('#page'))$('#page').innerHTML=`<div class="ss-page">${html}</div>`;}
function field(name,label,value='',opts={}){const t=opts.type||'text',help=opts.help?`<small>${opts.help}</small>`:'';return `<label class="ss-field">${label}${help}<input name="${rawEscape(name)}" type="${rawEscape(t)}" value="${rawEscape(value)}" ${t==='number'?`min="${opts.min??0}" step="${opts.step||'any'}"`:''} ${opts.required?'required':''} ${opts.readonly?'readonly':''} ${opts.placeholder?`placeholder="${rawEscape(opts.placeholder)}"`:''}></label>`;}
function selectField(name,label,options,value='',opts={}){return `<label class="ss-field">${label}${opts.help?`<small>${opts.help}</small>`:''}<select name="${rawEscape(name)}" ${opts.required?'required':''}>${options.map(o=>{const v=Array.isArray(o)?o[0]:typeof o==='object'?o.value:o,l=Array.isArray(o)?o[1]:typeof o==='object'?o.label:o;return `<option value="${rawEscape(v)}" ${String(value)===String(v)?'selected':''}>${rawEscape(l)}</option>`}).join('')}</select></label>`;}
let modalSeq=0;
function modal(ctx,title,content,wide=false,onClose=null){
  const el=document.createElement('div'),titleId=`ssModalTitle${++modalSeq}`;
  el.className='ss-modal-backdrop';
  el.innerHTML=`<section class="ss-modal ${wide?'ss-modal-wide':''}" role="dialog" aria-modal="true" aria-labelledby="${titleId}"><header><div><span class="ss-eyebrow">EMS · SUPERSHOP</span><h2 id="${titleId}">${rawEscape(title)}</h2></div><button type="button" class="ss-modal-close" aria-label="Close">×</button></header><div class="ss-modal-body">${content}</div></section>`;
  document.body.append(el);
  const escKey=e=>{if(e.key==='Escape')close()};
  /* close() is idempotent: the ✕ button, a backdrop click and Escape all
     land here, and callers that remove the modal themselves never trigger
     onClose twice. */
  function close(){document.removeEventListener('keydown',escKey);if(!el.isConnected)return;el.remove();if(onClose)onClose()}
  el.querySelector('.ss-modal-close').onclick=close;
  el.addEventListener('click',e=>{if(e.target===el)close()});
  document.addEventListener('keydown',escKey);
  return el;
}
function noWrite(ctx){return !!(ctx.state?.readOnly||ctx.state?.licenseExpired||ctx.state?.store?.status==='read_only')}
function toastError(ctx,error){ctx.toast(error?.message||String(error||'Request failed.'));}
const paymentOptions=[['cash','Cash'],['bank','Card / bank'],['bkash','bKash'],['nagad','Nagad'],['other','Other']];
const reasons=['Customer Changed Mind','Defective','Wrong Product','Damaged','Wrong Specification','Other'];
const returnConditions=['Sellable','Damaged','Defective'];
const unitFor=(product,label)=>product?.units?.find(u=>String(u.unit_label).toLowerCase()===String(label).toLowerCase());
const usableUnits=(product,kind='sale')=>(product?.units||[]).filter(u=>kind==='purchase'?u.can_purchase:u.can_sell);
const unitPrice=(product,unit,kind='sale')=>kind==='purchase'?(unit?.purchase_price==null?n(product?.purchase_price):n(unit.purchase_price)):(unit?.selling_price==null?n(product?.sale_price)*n(unit?.factor_to_base,1):n(unit.selling_price));
function csvMatrix(text){
  const rows=[];let row=[],cell='',quoted=false;
  for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){cell+='"';i++}else if(ch==='"')quoted=false;else cell+=ch}else if(ch==='"')quoted=true;else if(ch===','){row.push(cell);cell=''}else if(ch==='\n'){row.push(cell);rows.push(row);row=[];cell=''}else if(ch!=='\r')cell+=ch}
  if(cell.length||row.length){row.push(cell);rows.push(row)}
  if(!rows.length)return [];
  const headers=rows.shift().map(x=>x.trim().toLowerCase().replace(/\s+/g,'_'));
  return rows.filter(r=>r.some(x=>x.trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()])));
}

export async function sshopDashboard(ctx){
  const [d,alerts]=await Promise.all([ctx.api(`supershop/overview?today=${dateYmd()}`),ctx.api('supershop/alerts').catch(()=>[])]);if(!okCurrent(ctx))return;
  const actions=`${!noWrite(ctx)&&ctx.canAccess('sales','add')&&ctx.canAccess('inventory','view')?button(ctx,'＋ Quick sale','supershop-pos','primary'):''}${!noWrite(ctx)&&ctx.canAccess('purchase','add')&&ctx.canAccess('inventory','view')?button(ctx,'＋ Receive purchase','supershop-receive'):''}${!noWrite(ctx)&&ctx.canAccess('inventory','view')&&ctx.canAccess('inventory','add')?button(ctx,'＋ Add product','ss-add-product'):''}${!noWrite(ctx)&&ctx.canAccess('inventory','view')&&ctx.canAccess('inventory','edit')?button(ctx,'Adjust stock','ss-adjust-stock'):''}`;
  const low=(d.low_stock_products||[]).slice(0,6).map(p=>`<tr><td><b>${esc(ctx,p.name)}</b><small>${esc(ctx,p.sku||p.barcode||'')}</small></td><td>${r3(p.total_stock)} ${esc(ctx,p.base_unit)}</td><td>${r3(p.reorder_threshold)} ${esc(ctx,p.base_unit)}</td><td>${status(Number(p.total_stock)<=0?'Out of stock':'Reorder',Number(p.total_stock)<=0?'bad':'warning')}</td></tr>`);
  const activeAlerts=(alerts||[]).filter(a=>a.status!=='resolved').slice(0,4).map(a=>`<article class="ss-alert-row ss-alert-${esc(ctx,a.severity||'warning')}"><span>${icon(ctx,a.severity==='critical'?'alert-triangle':'bell')}</span><div><b>${esc(ctx,a.title)}</b><small>${esc(ctx,a.detail)}</small></div>${!noWrite(ctx)&&ctx.canAccess('inventory','edit')?`<button type="button" data-ss-read-alert="${rawEscape(a.id)}" aria-label="Mark alert read">✓</button>`:''}</article>`);
  const recent=(d.recent||[]).map(x=>`<tr><td>${status(x.kind==='sale'?'Sale':'Purchase',x.kind==='sale'?'good':'warning')}</td><td><code>${esc(ctx,x.invoice_number)}</code></td><td>${esc(ctx,x.party_name||'Walk-in')}</td><td>${fmtDate(x.invoice_date)}</td><td><b>${money(ctx,x.total||0)}</b></td></tr>`);
  page(ctx,`${pageActions(actions)}<div class="ss-kpis">${kpi(ctx,'receipt','Sales today',money(ctx,d.today_sales),'Posted sales','blue')}${kpi(ctx,'cart','Purchases today',money(ctx,d.today_purchases),'Supplier receipts','amber')}${kpi(ctx,'package','Inventory value',money(ctx,d.stock_value),'Weighted-average base cost','green')}${kpi(ctx,'alert-triangle','Low stock',d.low_stock_count,'At or below reorder level','rose')}${kpi(ctx,'users','Customer dues',money(ctx,d.customer_due),'Open sales invoices','violet')}${kpi(ctx,'truck','Supplier dues',money(ctx,d.supplier_due),'After purchase returns','cyan')}</div>
  <div class="ss-dashboard-grid">${ctx.canAccess('inventory','view')?`<section class="ss-panel"><header class="ss-panel-head"><div><span class="ss-eyebrow">ATTENTION</span><h2>Reorder watch</h2></div><button type="button" class="ss-link" data-ss-action="supershop-products">View catalog →</button></header>${table(['Product','On hand','Reorder at','Status'],low,'No products are below their reorder threshold.')}</section><section class="ss-panel"><header class="ss-panel-head"><div><span class="ss-eyebrow">NOTIFICATIONS</span><h2>Stock alerts</h2></div><button type="button" class="ss-link" data-ss-action="supershop-alerts">All alerts →</button></header><div class="ss-alert-list">${activeAlerts.join('')||empty('No active stock alerts.')}</div></section>`:''}</div>
  ${panel('Recent activity','Latest Supershop receipts and sales.',table(['Type','Invoice','Party','Date','Total'],recent,'No Supershop activity yet.'),`${ctx.canAccess('sales','view')?'<button type="button" class="ss-link" data-ss-action="supershop-sales">Sales →</button>':''}${ctx.canAccess('purchase','view')?'<button type="button" class="ss-link" data-ss-action="supershop-purchases">Purchases →</button>':''}`)}
  <div class="ss-quick-links">${!noWrite(ctx)&&ctx.canAccess('expense','add')?`<button data-ss-action="expense">${icon(ctx,'wallet')} Add expense</button>`:''}${ctx.canAccess('due_recover','view')?`<button data-ss-action="due-recover">${icon(ctx,'coins')} Recover due</button>`:''}${ctx.canAccess('report','view')?`<button data-ss-action="supershop-reports">${icon(ctx,'chart')} View reports</button>`:''}${ctx.canAccess('supplier','view')?`<button data-ss-action="suppliers">${icon(ctx,'truck')} Manage suppliers</button>`:''}</div>`);
  bindNav(ctx);document.querySelectorAll('[data-ss-read-alert]').forEach(b=>b.onclick=async()=>{try{await ctx.api(`supershop/alerts/${encodeURIComponent(b.dataset.ssReadAlert)}/read`,{method:'POST',body:'{}'});b.closest('.ss-alert-row')?.remove()}catch(e){toastError(ctx,e)}});
  if(!noWrite(ctx)&&ctx.canAccess('inventory','view')&&ctx.canAccess('inventory','add'))document.querySelector('[data-ss-action="ss-add-product"]')?.addEventListener('click',async()=>{try{const data=await ctx.api('supershop/products');productModal(ctx,null,data.products,()=>ctx.navigate('supershop-products'),data.suppliers)}catch(e){toastError(ctx,e)}});
  if(!noWrite(ctx)&&ctx.canAccess('inventory','view')&&ctx.canAccess('inventory','edit'))document.querySelector('[data-ss-action="ss-adjust-stock"]')?.addEventListener('click',async()=>{try{const data=await ctx.api('supershop/products');stockAdjustmentModal(ctx,data.products,()=>ctx.navigate('supershop-dashboard'))}catch(e){toastError(ctx,e)}});
}

export async function sshopProducts(ctx){
  const data=await ctx.api('supershop/products');if(!okCurrent(ctx))return;
  const actions=`${!noWrite(ctx)&&ctx.canAccess('inventory','add')?button(ctx,'＋ Add product','ss-add-product','primary'):''}${!noWrite(ctx)&&ctx.canAccess('inventory','add')?button(ctx,'Import CSV','ss-import'):''}${!noWrite(ctx)&&ctx.canAccess('inventory','edit')?button(ctx,'Configure categories','ss-categories'):''}${!noWrite(ctx)&&ctx.canAccess('inventory','edit')?button(ctx,'Stock adjustment','ss-adjust-stock'):''}`;
  page(ctx,`${pageActions(actions)}<section class="ss-panel"><div class="ss-filterbar"><label class="ss-search">${icon(ctx,'search')}<input id="ssProductSearch" type="search" placeholder="Search product, SKU, barcode or brand…"></label><select id="ssCategoryFilter"><option value="">All categories</option>${data.categories.map(c=>`<option value="${esc(ctx,c)}">${esc(ctx,c)}</option>`).join('')}</select><select id="ssStockFilter"><option value="all">All stock</option><option value="low">Low stock</option><option value="out">Out of stock</option><option value="active">Active</option><option value="archived">Archived</option></select><span class="ss-count" id="ssProductCount">${data.products.length} products</span></div><div id="ssProductsTable"></div></section>
  <aside class="ss-info-strip"><b>Stock integrity</b><span>Purchases, POS, returns, exchanges and adjustments post conversion-aware movements on the server. Product edit keeps prior invoice unit snapshots intact.</span></aside>`);
  const draw=()=>{
    const q=($('#ssProductSearch')?.value||'').trim().toLowerCase(),category=$('#ssCategoryFilter')?.value||'',stock=$('#ssStockFilter')?.value||'all';
    let rows=data.products.filter(p=>{const match=!q||`${p.name} ${p.sku} ${p.barcode} ${p.brand} ${p.category} ${p.subcategory}`.toLowerCase().includes(q),cat=!category||p.category===category;
      const st=stock==='low'?p.active&&p.total_stock<=p.reorder_threshold:stock==='out'?p.active&&p.total_stock<=0:stock==='active'?p.active:stock==='archived'?!p.active:true;return match&&cat&&st;});
    $('#ssProductCount').textContent=`${rows.length} product${rows.length===1?'':'s'}`;
    const body=rows.map(p=>`<tr><td><div class="ss-product-cell"><span class="ss-product-icon">${icon(ctx,'package')}</span><div><b>${esc(ctx,p.name)}</b><small>${esc(ctx,[p.brand,p.subcategory].filter(Boolean).join(' · ')||p.description||'')}</small></div></div></td><td><code>${esc(ctx,p.sku||'—')}</code><small>${esc(ctx,p.barcode||'')}</small></td><td>${esc(ctx,p.category||'Uncategorized')}${p.subcategory?`<small>${esc(ctx,p.subcategory)}</small>`:''}</td><td><b>${r3(p.total_stock)}</b> ${esc(ctx,p.base_unit)}</td><td>${money(ctx,p.average_cost_base)}<small>base cost</small></td><td>${money(ctx,p.mrp_per_base)}<small>MRP / base</small></td><td>${p.active?status(p.total_stock<=p.reorder_threshold?'Reorder':'Active',p.total_stock<=0?'bad':p.total_stock<=p.reorder_threshold?'warning':'good'):status('Archived')}</td><td><div class="ss-row-actions">${!noWrite(ctx)&&ctx.canAccess('inventory','edit')?`<button data-ss-edit-product="${p.id}" title="Edit product">Edit</button><button data-ss-adjust-product="${p.id}" title="Adjust stock">Stock</button>`:''}${!noWrite(ctx)&&ctx.canAccess('inventory','delete')&&p.active?`<button class="danger" data-ss-archive-product="${p.id}" title="Archive product">Archive</button>`:''}</div></td></tr>`);
    $('#ssProductsTable').innerHTML=table(['Product','SKU / barcode','Category','On hand','Avg cost','MRP','Status','Actions'],body,'No products match these filters.');
    document.querySelectorAll('[data-ss-edit-product]').forEach(b=>b.onclick=()=>productModal(ctx,data.products.find(x=>x.id===b.dataset.ssEditProduct),data.products,()=>sshopProducts(ctx),data.suppliers));
    document.querySelectorAll('[data-ss-adjust-product]').forEach(b=>b.onclick=()=>stockAdjustmentModal(ctx,data.products,()=>sshopProducts(ctx),b.dataset.ssAdjustProduct));
    document.querySelectorAll('[data-ss-archive-product]').forEach(b=>b.onclick=async()=>{const p=data.products.find(x=>x.id===b.dataset.ssArchiveProduct);if(!confirm(`Archive ${p?.name||'this product'}? It remains in transaction history.`))return;try{await ctx.api(`supershop/products/${p.id}`,{method:'DELETE'});ctx.toast('Product archived.');sshopProducts(ctx)}catch(e){toastError(ctx,e)}});
  };
  $('#ssProductSearch').oninput=draw;$('#ssCategoryFilter').onchange=draw;$('#ssStockFilter').onchange=draw;draw();
  bindNav(ctx);
  document.querySelector('[data-ss-action="ss-add-product"]')?.addEventListener('click',()=>productModal(ctx,null,data.products,()=>sshopProducts(ctx),data.suppliers));
  if(!noWrite(ctx))document.querySelector('[data-ss-action="ss-import"]')?.addEventListener('click',()=>importModal(ctx,()=>sshopProducts(ctx)));
  if(!noWrite(ctx))document.querySelector('[data-ss-action="ss-categories"]')?.addEventListener('click',()=>categoryModal(ctx,data,()=>sshopProducts(ctx)));
  if(!noWrite(ctx))document.querySelector('[data-ss-action="ss-adjust-stock"]')?.addEventListener('click',()=>stockAdjustmentModal(ctx,data.products,()=>sshopProducts(ctx)));
}
function productModal(ctx,product,products,refresh,suppliers=[]){
  if(noWrite(ctx)){ctx.toast('This shop is read-only.');return}
  const units=product?.units?.length?product.units.map(x=>({...x})):[{unit_label:product?.base_unit||'piece',factor_to_base:1,allow_fractional:false,can_purchase:true,can_sell:true,purchase_price:null,selling_price:null}];
  const base=product?.base_unit||'piece',unitRows=units.map(u=>unitRow(u,base)).join(''),supplierField=(suppliers?.length||!product?.default_supplier_id)?`<label class="ss-field">Default supplier<select name="default_supplier_id"><option value="">No default supplier</option>${(suppliers||[]).map(x=>`<option value="${rawEscape(x.id)}" ${product?.default_supplier_id===x.id?'selected':''}>${esc(ctx,x.name)}</option>`).join('')}</select></label>`:`<label class="ss-field">Default supplier<input type="hidden" name="default_supplier_id" value="${rawEscape(product.default_supplier_id)}"><input readonly value="Linked supplier"><small>Supplier details are hidden by your permissions; the existing link will be preserved.</small></label>`;
  const content=`<form id="ssProductForm" class="ss-form"><div class="ss-form-grid">
    ${field('name','Product name',product?.name||'',{required:true,placeholder:'e.g. Long-grain rice'})}
    ${field('sku','SKU / item code',product?.sku||'',{placeholder:'Leave blank for an EMS code'})}
    ${field('barcode','Barcode',product?.barcode||'',{placeholder:'Scan or type barcode'})}
    ${field('brand','Brand',product?.brand||'')}
    <label class="ss-field">Category<input name="category" list="ssCategoryList" value="${rawEscape(product?.category||'')}" placeholder="Create or choose a category"><datalist id="ssCategoryList">${[...new Set((products||[]).map(x=>x.category).filter(Boolean))].map(x=>`<option value="${rawEscape(x)}">`).join('')}</datalist></label>
    <label class="ss-field">Subcategory<input name="subcategory" list="ssSubcategoryList" value="${rawEscape(product?.subcategory||'')}" placeholder="Optional subcategory"><datalist id="ssSubcategoryList">${[...new Set((products||[]).map(x=>x.subcategory).filter(Boolean))].map(x=>`<option value="${rawEscape(x)}">`).join('')}</datalist></label>
    ${field('base_unit','Base stock unit',base,{required:true,placeholder:'piece, kg, L, meter…',help:'Inventory is stored in this unit. No universal pack size is assumed.'})}
    ${supplierField}
    ${field('purchase_price','Opening cost / base unit',product?.purchase_price??0,{type:'number',step:'0.01',help:'Used as starting average cost when the product has no stock.'})}
    ${field('sale_price','Selling price / base unit',product?.sale_price??0,{type:'number',step:'0.01'})}
    ${field('mrp_per_base','MRP / base unit',product?.mrp_per_base??product?.sale_price??0,{type:'number',step:'0.01'})}
    ${field('tax_percent','Default tax %',product?.tax_percent??0,{type:'number',step:'0.001',min:0})}
    ${field('reorder_threshold','Low-stock threshold (base units)',product?.reorder_threshold??5,{type:'number',step:'0.001',min:0})}
    ${!product?`<label class="ss-field">Opening stock<small>After creating the product, use Stock adjustment to record an auditable opening balance, or post a supplier receipt.</small></label>`:`<label class="ss-field">Current stock<input readonly value="${r3(product.total_stock)} ${rawEscape(product.base_unit)}"><small>Use Stock adjustment to change on-hand quantity.</small></label>`}
    <label class="ss-field ss-field-full">Product notes / description<textarea name="description" rows="3" maxlength="2000" placeholder="Optional product details">${rawEscape(product?.description||'')}</textarea></label>
  </div><section class="ss-unit-editor"><header><div><b>Per-product unit conversions</b><small>Factor is the number of base units inside one purchase / sale unit. Decimal quantities are enabled per unit.</small></div><button type="button" class="ss-link" id="ssAddUnit">＋ Add unit</button></header><div class="ss-unit-grid ss-unit-labels"><span>Unit label</span><span>Base units / unit</span><span>Purchase price</span><span>Sell price</span><span>Decimal</span><span>Buy</span><span>Sell</span><span></span></div><div id="ssUnitRows">${unitRows}</div></section>
  <div class="ss-form-footer"><span>Updates preserve historic invoice lines and stock movements.</span><button type="submit" class="ss-btn ss-btn-primary">${product?'Save product':'Create product'}</button></div></form>`;
  const el=modal(ctx,product?'Edit product':'Add product',content,true),rows=el.querySelector('#ssUnitRows');
  const addUnit=()=>{rows.insertAdjacentHTML('beforeend',unitRow({unit_label:'',factor_to_base:1,allow_fractional:false,can_purchase:true,can_sell:true,purchase_price:'',selling_price:''},el.querySelector('[name="base_unit"]').value));bindUnitRows(el)};
  el.querySelector('#ssAddUnit').onclick=addUnit;
  el.querySelector('[name="base_unit"]').addEventListener('input',ev=>{const baseRow=el.querySelector('[data-ss-base-unit]');if(baseRow)baseRow.value=ev.target.value.toLowerCase()});
  bindUnitRows(el);
  el.querySelector('#ssProductForm').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),baseUnit=String(f.base_unit||'piece').trim().toLowerCase();
    const unitData=[...rows.querySelectorAll('.ss-unit-row')].map(row=>({unit_label:row.querySelector('[data-unit-label]').value.trim().toLowerCase(),factor_to_base:Number(row.querySelector('[data-unit-factor]').value),purchase_price:row.querySelector('[data-unit-purchase-price]').value===''?null:Number(row.querySelector('[data-unit-purchase-price]').value),selling_price:row.querySelector('[data-unit-sell-price]').value===''?null:Number(row.querySelector('[data-unit-sell-price]').value),allow_fractional:row.querySelector('[data-unit-fractional]').checked,can_purchase:row.querySelector('[data-unit-buy]').checked,can_sell:row.querySelector('[data-unit-sell]').checked})).filter(x=>x.unit_label);
    const productData={...f,base_unit:baseUnit,units:unitData,purchase_price:Number(f.purchase_price||0),sale_price:Number(f.sale_price||0),mrp_per_base:Number(f.mrp_per_base||0),tax_percent:Number(f.tax_percent||0),reorder_threshold:Number(f.reorder_threshold||0),default_supplier_id:f.default_supplier_id||null};
    try{const saved=await ctx.api(product?`supershop/products/${product.id}`:'supershop/products',{method:product?'PATCH':'POST',body:JSON.stringify(productData)});el.remove();ctx.toast(product?'Product updated.':'Product added to catalog.');refresh(saved)}catch(e){toastError(ctx,e)}
  };
}
function unitRow(u,base){const isBase=String(u.unit_label||'').toLowerCase()===String(base||'').toLowerCase();return `<div class="ss-unit-row" data-ss-base="${isBase?'1':'0'}"><input data-unit-label ${isBase?'data-ss-base-unit':''} value="${rawEscape(u.unit_label||'')}" ${isBase?'readonly':''} placeholder="e.g. pack"><input data-unit-factor type="number" min="0.000001" step="any" value="${isBase?1:rawEscape(u.factor_to_base??1)}" ${isBase?'readonly':''} aria-label="Base units per unit"><input data-unit-purchase-price type="number" min="0" step="0.01" value="${u.purchase_price??''}" aria-label="Purchase price"><input data-unit-sell-price type="number" min="0" step="0.01" value="${u.selling_price??''}" aria-label="Selling price"><label class="ss-check"><input data-unit-fractional type="checkbox" ${u.allow_fractional?'checked':''} aria-label="Allow decimal quantities"></label><label class="ss-check"><input data-unit-buy type="checkbox" ${u.can_purchase?'checked':''} aria-label="Allow purchase"></label><label class="ss-check"><input data-unit-sell type="checkbox" ${u.can_sell!==false?'checked':''} aria-label="Allow sale"></label><button type="button" data-unit-remove ${isBase?'disabled':''} aria-label="Remove unit">×</button></div>`;}
function bindUnitRows(el){el.querySelectorAll('[data-unit-remove]').forEach(b=>b.onclick=()=>{if(!b.disabled)b.closest('.ss-unit-row').remove()})}

function stockAdjustmentModal(ctx,products,refresh,productId=null){
  if(noWrite(ctx)){ctx.toast('This shop is read-only.');return}
  const active=products.filter(x=>x.active),item=active.find(x=>x.id===productId)||active[0];if(!item){ctx.toast('Add a product before adjusting stock.');return}
  const productOptions=active.map(p=>`<option value="${p.id}" ${p.id===item.id?'selected':''}>${rawEscape(p.name)} · ${r3(p.total_stock)} ${rawEscape(p.base_unit)}</option>`).join('');
  const e=modal(ctx,'Stock adjustment',`<form id="ssAdjustForm" class="ss-form"><p class="ss-callout">This posts an auditable movement against aggregate stock. Negative stock is blocked server-side.</p>
    <label class="ss-field">Product<select name="productId" id="ssAdjustProduct">${productOptions}</select></label>
    <label class="ss-field">Adjustment type<select name="mode"><option value="increase">Add stock</option><option value="decrease">Remove stock</option><option value="count">Set counted stock</option></select></label>
    ${field('quantity','Quantity (base units)',1,{type:'number',min:0.001,step:'0.001',required:true})}
    ${selectField('reason','Reason',[['correction','Stock correction'],['damage','Damaged goods'],['waste','Waste / breakage'],['opening','Opening stock'],['count','Physical stock count']], 'correction')}
    ${field('notes','Notes','',{placeholder:'Optional reference / explanation'})}
    <div class="ss-adjust-stock" id="ssCurrentStock">Current stock: ${r3(item.total_stock)} ${rawEscape(item.base_unit)}</div>
    <div class="ss-form-footer"><span>Movement and before / after values are recorded.</span><button class="ss-btn ss-btn-primary">Post adjustment</button></div></form>`,false);
  const update=()=>{const p=active.find(x=>x.id===e.querySelector('[name="productId"]').value);e.querySelector('#ssCurrentStock').textContent=`Current stock: ${r3(p?.total_stock)} ${p?.base_unit||''}`};e.querySelector('#ssAdjustProduct').onchange=update;const reasonSelect=e.querySelector('[name="reason"]'),modeSelect=e.querySelector('[name="mode"]');reasonSelect.onchange=()=>{if(['damage','waste'].includes(reasonSelect.value))modeSelect.value='decrease';else if(reasonSelect.value==='opening')modeSelect.value='increase'};const idempotencyKey=uid();
  e.querySelector('#ssAdjustForm').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),qty=Number(f.quantity),mode=f.mode,reason=f.reason;let movementType=reason==='damage'?'damage':reason==='waste'?'waste':reason==='opening'?'opening':mode==='count'?'stock_count':'adjustment';const body={productId:f.productId,movementType,reason:`${reason}: ${f.notes||''}`.trim(),idempotencyKey};if(mode==='count')body.targetQuantity=qty;else body.delta=mode==='decrease'?-qty:qty;
    try{await ctx.api('supershop/stock-adjustments',{method:'POST',body:JSON.stringify(body)});e.remove();ctx.toast('Stock movement posted.');refresh()}catch(err){toastError(ctx,err)}};
}

function categoryModal(ctx,data,refresh){
  if(noWrite(ctx)){ctx.toast('This shop is read-only.');return}
  const cats=data.categories||[],subs=data.subcategories||[];if(!cats.length){ctx.toast('Add a category in a product editor first.');return}
  const e=modal(ctx,'Configure categories',`<p class="ss-callout">Category and subcategory labels are created in product setup. Rename a label here to update every Supershop product currently using it.</p><form id="ssCategoryForm" class="ss-form">
  ${selectField('oldCategory','Category to rename',cats,cats[0],{required:true})}${field('newCategory','New category name','',{required:true,placeholder:'Enter the replacement label'})}
  <label class="ss-field">Subcategory to rename (optional)<select name="oldSubcategory"><option value="">Do not rename a subcategory</option>${subs.map(x=>`<option value="${rawEscape(x)}">${rawEscape(x)}</option>`).join('')}</select></label>${field('newSubcategory','New subcategory label','',{placeholder:'Optional'})}
  <div class="ss-form-footer"><span>This is a catalog label change only.</span><button class="ss-btn ss-btn-primary">Rename label</button></div></form>`);
  e.querySelector('#ssCategoryForm').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));try{await ctx.api('supershop/categories/rename',{method:'POST',body:JSON.stringify(f)});e.remove();ctx.toast('Category labels updated.');refresh()}catch(err){toastError(ctx,err)}};
}
function importModal(ctx,refresh){
  if(noWrite(ctx)){ctx.toast('This shop is read-only.');return}
  const e=modal(ctx,'Import products from CSV',`<p class="ss-callout">Accepted columns: name, sku, barcode, brand, category, subcategory, base_unit, purchase_price, sale_price, mrp_per_base, tax_percent, reorder_threshold, description, allow_fractional. Imports start at zero stock; configure extra packs or use an opening-stock adjustment after import.</p>
   <form id="ssImportForm" class="ss-form"><label class="ss-field">CSV file<input id="ssCsvFile" type="file" accept=".csv,text/csv" required></label><div id="ssImportPreview" class="ss-import-preview">Choose a CSV file to preview its rows.</div><div class="ss-form-footer"><span>Up to 100 rows per import. Failed rows are reported individually.</span><button id="ssImportSubmit" class="ss-btn ss-btn-primary" disabled>Import products</button></div></form>`);
  let parsed=[];const input=e.querySelector('#ssCsvFile');input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;parsed=csvMatrix(await file.text()).slice(0,100);e.querySelector('#ssImportPreview').innerHTML=`<b>${parsed.length} rows ready</b>${table(['Name','SKU','Base unit'],parsed.slice(0,6).map(x=>`<tr><td>${rawEscape(x.name||'')}</td><td>${rawEscape(x.sku||'')}</td><td>${rawEscape(x.base_unit||'piece')}</td></tr>`),'No data rows found in this file.')}`;e.querySelector('#ssImportSubmit').disabled=!parsed.length}catch(err){toastError(ctx,err)}};
  e.querySelector('#ssImportForm').onsubmit=async ev=>{ev.preventDefault();if(!parsed.length)return;const button=e.querySelector('#ssImportSubmit');button.disabled=true;button.textContent='Importing…';try{const out=await ctx.api('supershop/products/import',{method:'POST',body:JSON.stringify({items:parsed})});const failures=out.results.filter(x=>!x.ok);e.querySelector('#ssImportPreview').innerHTML=`<b>${out.success} imported · ${out.failed} failed</b>${failures.length?`<ul>${failures.map(x=>`<li>Row ${x.row}${x.name?` (${rawEscape(x.name)})`:''}: ${rawEscape(x.error)}</li>`).join('')}</ul>`:'<p>All rows imported successfully.</p>'}`;ctx.toast(`${out.success} products imported.`);button.type='button';button.textContent='Done';button.disabled=false;button.onclick=()=>{e.remove();refresh()}}catch(err){button.disabled=false;button.textContent='Import products';toastError(ctx,err)}};
}

export async function sshopPOS(ctx,kind='sale'){
  const [catalog,customers,suppliers]=await Promise.all([ctx.api('supershop/products'),ctx.canAccess('customer','view')?ctx.api('customers').catch(()=>[]):Promise.resolve([]),ctx.canAccess('supplier','view')?ctx.api('suppliers').catch(()=>[]):Promise.resolve([])]);if(!okCurrent(ctx))return;
  const products=catalog.products.filter(p=>p.active),isPurchase=kind==='purchase',items=products.filter(p=>usableUnits(p,kind).length),cart=[];
  const options=(isPurchase?suppliers:customers).map(x=>`<option value="${x.id}">${rawEscape(x.name)}${x.phone?` · ${rawEscape(x.phone)}`:''}</option>`).join('');
  page(ctx,`${pageActions(`<button class="ss-btn" data-ss-action="${isPurchase?'supershop-purchases':'supershop-sales'}">${isPurchase?'Purchase history':'Sales history'}</button>`)}<div class="ss-pos-layout"><section class="ss-panel ss-pos-catalog"><header class="ss-panel-head"><div><span class="ss-eyebrow">CATALOG</span><h2>Select products</h2></div><span class="ss-count">${items.length} active</span></header><label class="ss-search ss-pos-search">${icon(ctx,'search')}<input id="ssPosSearch" type="search" autocomplete="off" placeholder="Search or scan barcode, SKU, product…"><kbd>/</kbd></label><div class="ss-pos-products" id="ssPosProducts"></div></section>
  <section class="ss-panel ss-pos-checkout"><header class="ss-panel-head"><div><span class="ss-eyebrow">${isPurchase?'SUPPLIER RECEIPT':'CURRENT SALE'}</span><h2>${isPurchase?'Purchase cart':'Sale cart'}</h2></div><button type="button" class="ss-link" id="ssClearCart">Clear</button></header><form id="ssCheckoutForm"><div id="ssCartLines"></div>
   <div class="ss-party-fields"><label class="ss-field">${isPurchase?'Supplier':'Customer'}<select name="partyId"><option value="">${isPurchase?'Select supplier (optional)':'Walk-in / choose customer'}</option>${options}</select></label><details class="ss-custom-party"><summary>Use a one-time ${isPurchase?'supplier':'customer'}</summary><div class="ss-custom-grid">${field('customName','Name','',{placeholder:'Name'})}${field('customPhone','Phone','',{placeholder:'Phone'})}${field('customAddress','Address','',{placeholder:'Address'})}</div></details></div>
   <div class="ss-totals"><div><span>Subtotal</span><b id="ssSubtotal">৳ 0.00</b></div><div><span>Invoice tax %</span><input name="taxPercent" id="ssTaxPercent" type="number" min="0" max="100" step="0.001" value="0"></div><div><span>Invoice discount</span><input name="discount" id="ssDiscount" type="number" min="0" step="0.01" value="0"></div><div class="ss-grand-total"><span>Total</span><b id="ssGrandTotal">৳ 0.00</b></div></div>
   <div class="ss-payment-grid"><label class="ss-field">Payment method<select name="paymentMethod">${paymentOptions.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label>${field('paidAmount','Paid now',0,{type:'number',step:'0.01',min:0})}${field('transactionId','Transaction / reference','',{placeholder:'Optional'})}</div>
   ${field('notes','Notes','',{placeholder:'Optional invoice note'})}<div class="ss-pos-due"><span>Balance due</span><b id="ssDueAmount">৳ 0.00</b></div><button type="submit" id="ssPostInvoice" class="ss-btn ss-btn-primary ss-checkout-button" ${noWrite(ctx)?'disabled':''}>${isPurchase?'Post purchase receipt':'Complete sale'}</button><p class="ss-muted">Stock and invoice values are validated and committed together by EMS.</p></form></section></div>`);
  bindNav(ctx);
  const search=$('#ssPosSearch'),productRoot=$('#ssPosProducts'),cartRoot=$('#ssCartLines'),form=$('#ssCheckoutForm');let currentIdempotencyKey=uid();
  const drawProducts=(query='')=>{const q=query.trim().toLowerCase(),list=items.filter(p=>!q||`${p.name} ${p.sku} ${p.barcode} ${p.brand} ${p.category}`.toLowerCase().includes(q));productRoot.innerHTML=list.map(p=>{const baseUnit=usableUnits(p,kind).find(u=>u.unit_label===p.base_unit)||usableUnits(p,kind)[0],price=unitPrice(p,baseUnit,kind);return `<button type="button" class="ss-pos-product" data-ss-add="${p.id}"><span class="ss-pos-product-icon">${icon(ctx,'package')}</span><span class="ss-pos-product-info"><b>${rawEscape(p.name)}</b><small>${rawEscape([p.sku,p.category].filter(Boolean).join(' · ')||p.base_unit)}</small></span><span class="ss-pos-product-right"><b>${money(ctx,price)}</b><small>${isPurchase?'avg / base':'on hand '+r3(p.total_stock)+' '+rawEscape(p.base_unit)}</small></span></button>`}).join('')||empty('No matching products.');productRoot.querySelectorAll('[data-ss-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.ssAdd));};
  const addToCart=id=>{const p=items.find(x=>x.id===id);if(!p)return;const unit=usableUnits(p,kind).find(u=>u.unit_label===p.base_unit)||usableUnits(p,kind)[0];const key=`${id}|${unit.unit_label}`,existing=cart.find(x=>x.key===key);if(existing)existing.quantity=r3(existing.quantity+1);else cart.push({key,product:p,unitLabel:unit.unit_label,quantity:1,unitPrice:unitPrice(p,unit,kind),taxPercent:p.tax_percent||0,discount:0,freeQuantity:0});drawCart();};
  const totals=()=>{let subtotal=cart.reduce((s,x)=>s+r2(x.quantity*x.unitPrice),0),lineTax=cart.reduce((s,x)=>s+r2(x.quantity*x.unitPrice*x.taxPercent/100),0),lineDiscount=cart.reduce((s,x)=>s+n(x.discount),0),tax=r2(subtotal*n($('#ssTaxPercent')?.value)/100),discount=r2($('#ssDiscount')?.value||0);return {subtotal:r2(subtotal),total:r2(subtotal+lineTax+tax-lineDiscount-discount)}};
  const drawCart=()=>{
    cartRoot.innerHTML=cart.length?cart.map((x,index)=>{const units=usableUnits(x.product,kind);return `<article class="ss-cart-line" data-cart-index="${index}"><div class="ss-cart-line-head"><div><b>${rawEscape(x.product.name)}</b><small>${rawEscape(x.product.sku||x.product.barcode||'')} · stock ${r3(x.product.total_stock)} ${rawEscape(x.product.base_unit)}</small></div><button type="button" data-ss-remove="${index}" aria-label="Remove ${rawEscape(x.product.name)}">×</button></div><div class="ss-cart-inputs"><label>Unit<select data-cart-unit="${index}">${units.map(u=>`<option value="${rawEscape(u.unit_label)}" ${u.unit_label===x.unitLabel?'selected':''}>${rawEscape(u.unit_label)} × ${r3(u.factor_to_base)}</option>`).join('')}</select></label><label>Qty<input data-cart-qty="${index}" type="number" min="0.001" step="${unitFor(x.product,x.unitLabel)?.allow_fractional?'any':'1'}" value="${x.quantity}"></label><label>Price / unit<input data-cart-price="${index}" type="number" min="0" step="0.01" value="${x.unitPrice}" ${kind==='sale'&&!ctx.canAccess('sales','edit')?'readonly':''}></label>${isPurchase?`<label>Free qty<input data-cart-free="${index}" type="number" min="0" step="any" value="${x.freeQuantity||0}"></label>`:''}<label>Line discount<input data-cart-discount="${index}" type="number" min="0" step="0.01" value="${x.discount||0}"></label><span class="ss-cart-line-total">${money(ctx,r2(x.quantity*x.unitPrice+x.quantity*x.unitPrice*x.taxPercent/100-x.discount))}</span></div></article>`}).join(''):empty('Add products to build the transaction.');
    cartRoot.querySelectorAll('[data-ss-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.ssRemove),1);drawCart()});
    cartRoot.querySelectorAll('[data-cart-unit]').forEach(el=>el.onchange=()=>{const x=cart[Number(el.dataset.cartUnit)],unit=unitFor(x.product,el.value);if(!unit)return;x.unitLabel=unit.unit_label;x.unitPrice=unitPrice(x.product,unit,kind);drawCart()});
    cartRoot.querySelectorAll('[data-cart-qty]').forEach(el=>el.oninput=()=>{const x=cart[Number(el.dataset.cartQty)];x.quantity=n(el.value);const amount=el.closest('.ss-cart-line').querySelector('.ss-cart-line-total');amount.textContent=money(ctx,r2(x.quantity*x.unitPrice+x.quantity*x.unitPrice*x.taxPercent/100-x.discount));updateTotals()});
    cartRoot.querySelectorAll('[data-cart-price]').forEach(el=>el.oninput=()=>{const x=cart[Number(el.dataset.cartPrice)];x.unitPrice=n(el.value);el.closest('.ss-cart-line').querySelector('.ss-cart-line-total').textContent=money(ctx,r2(x.quantity*x.unitPrice+x.quantity*x.unitPrice*x.taxPercent/100-x.discount));updateTotals()});
    cartRoot.querySelectorAll('[data-cart-free]').forEach(el=>el.oninput=()=>{cart[Number(el.dataset.cartFree)].freeQuantity=n(el.value);updateTotals()});
    cartRoot.querySelectorAll('[data-cart-discount]').forEach(el=>el.oninput=()=>{const x=cart[Number(el.dataset.cartDiscount)];x.discount=n(el.value);el.closest('.ss-cart-line').querySelector('.ss-cart-line-total').textContent=money(ctx,r2(x.quantity*x.unitPrice+x.quantity*x.unitPrice*x.taxPercent/100-x.discount));updateTotals()});updateTotals();
  };
  const updateTotals=()=>{const t=totals(),paid=n(form?.querySelector('[name="paidAmount"]')?.value);$('#ssSubtotal').textContent=money(ctx,t.subtotal);$('#ssGrandTotal').textContent=money(ctx,t.total);$('#ssDueAmount').textContent=money(ctx,Math.max(0,r2(t.total-paid)));};
  search.oninput=()=>drawProducts(search.value);search.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const q=search.value.trim().toLowerCase(),match=items.find(p=>[p.barcode,p.sku,p.name].some(x=>String(x||'').toLowerCase()===q));if(match){addToCart(match.id);search.value='';drawProducts('')}}};
  document.addEventListener('keydown',function hotkey(e){if(!document.body.classList.contains('sshop-on')||!form.isConnected){document.removeEventListener('keydown',hotkey);return}if(e.key==='/'&&!e.target.matches('input,textarea,select')){e.preventDefault();search.focus()}if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();form.requestSubmit()}});
  $('#ssClearCart').onclick=()=>{cart.splice(0,cart.length);drawCart()};$('#ssTaxPercent').oninput=updateTotals;$('#ssDiscount').oninput=updateTotals;form.querySelector('[name="paidAmount"]').oninput=updateTotals;
  drawProducts();drawCart();
  form.onsubmit=async e=>{e.preventDefault();if(!cart.length){ctx.toast('Add at least one product.');return}const f=Object.fromEntries(new FormData(form)),t=totals();if(Number(f.paidAmount)>t.total){ctx.toast('Paid amount cannot exceed the invoice total.');return}
    const body={partyId:f.partyId||null,customParty:{name:f.customName||'',phone:f.customPhone||'',address:f.customAddress||''},paymentMethod:f.paymentMethod,transactionId:f.transactionId||'',notes:f.notes||'',taxPercent:Number(f.taxPercent||0),discount:Number(f.discount||0),paidAmount:Number(f.paidAmount||0),invoiceDate:dateYmd(),idempotencyKey:currentIdempotencyKey,lines:cart.map(x=>({productId:x.product.id,unitLabel:x.unitLabel,quantity:Number(x.quantity),freeQuantity:isPurchase?Number(x.freeQuantity||0):0,unitPrice:Number(x.unitPrice),taxPercent:Number(x.taxPercent),discount:Number(x.discount)}))};
    const submit=$('#ssPostInvoice');submit.disabled=true;submit.textContent='Posting securely…';try{const invoice=await ctx.api(isPurchase?'supershop/purchases':'supershop/sales',{method:'POST',body:JSON.stringify(body)});form.dataset.posted='true';cart.splice(0,cart.length);drawCart();receiptModal(ctx,invoice,kind,body.lines.map((line,i)=>({...line,product:products.find(p=>p.id===line.productId)})));ctx.toast(isPurchase?'Purchase receipt posted.':'Sale completed.');}catch(err){toastError(ctx,err)}finally{submit.disabled=noWrite(ctx)||form.dataset.posted==='true';submit.textContent=isPurchase?'Post purchase receipt':'Complete sale'};
  };
}

export async function sshopPurchases(ctx){
  const rows=await ctx.api('supershop/purchases');if(!okCurrent(ctx))return;
  const actions=`${!noWrite(ctx)&&ctx.canAccess('purchase','add')&&ctx.canAccess('inventory','view')?button(ctx,'＋ Receive purchase','supershop-receive','primary'):''}${ctx.canAccess('purchase','view')?button(ctx,'Supplier returns','supershop-supplier-returns'):''}`;
  page(ctx,`${pageActions(actions)}<section class="ss-panel"><div class="ss-filterbar"><label class="ss-search">${icon(ctx,'search')}<input id="ssPurchaseSearch" type="search" placeholder="Search invoice or supplier…"></label><span class="ss-count">${rows.length} receipts</span></div><div id="ssPurchaseRows"></div></section>`);
  const draw=()=>{const q=$('#ssPurchaseSearch').value.toLowerCase(),filtered=rows.filter(x=>`${x.invoice_number} ${x.party_name} ${x.notes||''}`.toLowerCase().includes(q));$('#ssPurchaseRows').innerHTML=table(['Invoice','Supplier','Date','Subtotal','Paid','Due','Status','Actions'],filtered.map(x=>`<tr><td><code>${esc(ctx,x.invoice_number)}</code></td><td>${esc(ctx,x.party_name||'Supplier not selected')}</td><td>${fmtDate(x.invoice_date)}</td><td>${money(ctx,x.total)}</td><td>${money(ctx,x.paid_amount)}</td><td>${money(ctx,x.total_due)}</td><td>${status(Number(x.total_due)>0?'Balance due':'Paid',Number(x.total_due)>0?'warning':'good')}</td><td><div class="ss-row-actions"><button data-ss-invoice-view="${x.id}" data-kind="purchase">View</button>${!noWrite(ctx)&&ctx.canAccess('purchase','add')?`<button data-ss-supplier-return="${x.id}">Return to supplier</button>`:''}</div></td></tr>`),'No purchase receipts yet.');
    document.querySelectorAll('[data-ss-invoice-view]').forEach(b=>b.onclick=()=>showInvoiceDetails(ctx,b.dataset.ssInvoiceView,'purchase',rows));document.querySelectorAll('[data-ss-supplier-return]').forEach(b=>b.onclick=()=>supplierReturnModal(ctx,b.dataset.ssSupplierReturn,rows,()=>sshopPurchases(ctx)));};
  $('#ssPurchaseSearch').oninput=draw;draw();bindNav(ctx);
}
