async function showInvoiceDetails(ctx,id,kind,records=[]){
  try{const d=await ctx.api(`supershop/${kind==='sale'?'sales':'purchases'}/${encodeURIComponent(id)}`),content=`<div class="ss-receipt-head"><b>${esc(ctx,d.invoice_number)}</b>${status(Number(d.total_due)>0?'Balance due':'Paid',Number(d.total_due)>0?'warning':'good')}<small>${fmtDate(d.invoice_date)} · ${esc(ctx,d.party_name||d.custom_party_name||'Walk-in')}</small></div>${table(['Product','Quantity','Unit','Price','Tax','Line total'],d.lines.map(x=>`<tr><td><b>${esc(ctx,x.product_name)}</b><small>${esc(ctx,x.sku)}</small></td><td>${r3(x.quantity)}${Number(x.free_quantity_base)>0?`<small>+ ${r3(x.free_quantity_base)} free base units</small>`:''}</td><td>${esc(ctx,x.unit_label)}</td><td>${money(ctx,x.unit_price)}</td><td>${n(x.tax_percent)}%</td><td>${money(ctx,x.line_total)}</td></tr>`),'No invoice lines.')}<div class="ss-receipt-totals"><div><span>Subtotal</span><b>${money(ctx,d.subtotal)}</b></div><div><span>Invoice tax</span><b>${money(ctx,d.tax_amount)}</b></div><div><span>Line tax</span><b>${money(ctx,d.line_tax_amount)}</b></div><div><span>Discount</span><b>${money(ctx,n(d.discount)+n(d.line_discount_amount))}</b></div><div class="strong"><span>Total</span><b>${money(ctx,d.total)}</b></div><div><span>Paid</span><b>${money(ctx,d.paid_amount)}</b></div><div><span>Due</span><b>${money(ctx,d.total_due)}</b></div></div><div class="ss-form-footer"><span>TrueBill token: <code>${esc(ctx,d.verification_token||'—')}</code></span><div><button type="button" class="ss-btn" id="ssPrintInvoice">Print</button>${kind==='sale'?`<button type="button" class="ss-btn ss-btn-primary" id="ssStartReturn">Return / exchange</button>`:''}</div></div>`;
    const e=modal(ctx,`${kind==='sale'?'Sales':'Purchase'} invoice`,content,true);e.querySelector('#ssPrintInvoice').onclick=()=>printInvoice(e,d,ctx);if(kind==='sale'&&e.querySelector('#ssStartReturn'))e.querySelector('#ssStartReturn').onclick=()=>{e.remove();customerReturnModal(ctx,records.length?records:[d],id)};
  }catch(e){toastError(ctx,e)}
}
function receiptModal(ctx,invoice,kind,cart){
  const total=n(invoice.total??(n(invoice.subtotal)+n(invoice.tax_amount)+n(invoice.line_tax_amount)-n(invoice.discount)-n(invoice.line_discount_amount)));
  const content=`<div class="ss-success-mark">${icon(ctx,'check')}</div><h3>${kind==='purchase'?'Purchase receipt posted':'Sale completed'}</h3><p>Invoice <b>${esc(ctx,invoice.invoice_number)}</b> was recorded with conversion-aware stock movements.</p><div class="ss-receipt-totals"><div><span>Total</span><b>${money(ctx,total)}</b></div><div><span>Paid</span><b>${money(ctx,invoice.paid_amount)}</b></div><div><span>Due</span><b>${money(ctx,invoice.total_due)}</b></div><div><span>Verification token</span><code>${esc(ctx,invoice.verification_token||'—')}</code></div></div><div class="ss-form-footer"><button type="button" id="ssReceiptPrint" class="ss-btn">Print receipt</button><div><button type="button" id="ssReceiptClose" class="ss-btn">Close</button><button type="button" id="ssReceiptHistory" class="ss-btn ss-btn-primary">${kind==='purchase'?'Purchase history':'Sales history'}</button></div></div>`;
  const historyPage=kind==='purchase'?'supershop-purchases':'supershop-sales';
  /* onClose matters: the POS submit button stays disabled after a successful
     post, so dismissing the receipt with ✕ / backdrop / Escape must still
     leave the counter instead of stranding the user on a locked form. */
  const e=modal(ctx,'Transaction posted',content,false,()=>ctx.navigate(historyPage));e.querySelector('#ssReceiptClose').onclick=()=>{e.remove();ctx.navigate(historyPage)};e.querySelector('#ssReceiptHistory').onclick=()=>{e.remove();ctx.navigate(historyPage)};e.querySelector('#ssReceiptPrint').onclick=()=>printInvoice(e,{...invoice,kind,total,items:cart},ctx);
}
function printInvoice(modalEl,invoice,ctx){
  if(!modalEl.querySelector('.ss-modal-body'))return;document.getElementById('ss-print-only')?.remove();const lines=invoice.lines||invoice.items||[],items=lines.map(x=>{const name=x.product_name||x.product?.name||x.name||'Product',qty=x.quantity??0,unit=x.unit_label||x.unitLabel||'',unitPrice=x.unit_price??x.unitPrice??0,total=x.line_total??x.total_amount??(Number(qty)*Number(unitPrice)+Number(qty)*Number(unitPrice)*Number(x.taxPercent||x.tax_percent||0)/100-Number(x.discount||0));return `<tr><td>${rawEscape(name)}${x.sku?`<small>${rawEscape(x.sku)}</small>`:''}</td><td>${rawEscape(qty)} ${rawEscape(unit)}</td><td>৳ ${Number(unitPrice||0).toFixed(2)}</td><td>৳ ${Number(total||0).toFixed(2)}</td></tr>`}).join('');const print=document.createElement('div');print.id='ss-print-only';print.innerHTML=`<h1>${rawEscape(ctx.state?.store?.name||'EMS Supershop')}</h1><p>${rawEscape(invoice.kind==='purchase'?'Purchase receipt':'Sales receipt')} · ${rawEscape(invoice.invoice_number||'')}</p><p>${rawEscape(fmtDate(invoice.invoice_date))} · ${rawEscape(invoice.party_name||invoice.custom_party_name||'Walk-in')}</p><table><thead><tr><th>Product</th><th>Quantity</th><th>Price</th><th>Total</th></tr></thead><tbody>${items}</tbody></table><hr><p>Subtotal: ৳ ${Number(invoice.subtotal||0).toFixed(2)} · Tax: ৳ ${Number(invoice.tax_amount||0).toFixed(2)} · Discount: ৳ ${Number(invoice.discount||0).toFixed(2)}</p><p><b>Total: ৳ ${Number(invoice.total??invoice.subtotal??0).toFixed(2)} · Paid: ৳ ${Number(invoice.paid_amount||0).toFixed(2)} · Due: ৳ ${Number(invoice.total_due||0).toFixed(2)}</b></p><p>Verification: ${rawEscape(invoice.verification_token||'—')}</p>`;document.body.append(print);window.print();print.remove();}

export async function sshopMovements(ctx){
  const [rows,data]=await Promise.all([ctx.api('supershop/stock-movements'),ctx.api('supershop/products')]);if(!okCurrent(ctx))return;
  const action=!noWrite(ctx)&&ctx.canAccess('inventory','edit')?button(ctx,'＋ Stock adjustment','ss-adjust-stock','primary'):'';
  page(ctx,`${pageActions(action)}<section class="ss-panel"><div class="ss-filterbar"><label class="ss-search">${icon(ctx,'search')}<input id="ssMovementSearch" type="search" placeholder="Search product, movement or reason…"></label><select id="ssMovementType"><option value="">All movements</option>${[...new Set(rows.map(x=>x.movement_type))].sort().map(x=>`<option value="${rawEscape(x)}">${rawEscape(x.replaceAll('_',' '))}</option>`).join('')}</select><span class="ss-count">${rows.length} movements</span></div><div id="ssMovementsTable"></div></section>`);
  const draw=()=>{const q=$('#ssMovementSearch').value.toLowerCase(),t=$('#ssMovementType').value,filtered=rows.filter(x=>(!t||x.movement_type===t)&&`${x.product_name} ${x.sku} ${x.reason} ${x.reference_type}`.toLowerCase().includes(q));$('#ssMovementsTable').innerHTML=table(['Date','Product','Movement','Quantity','Before → after','Reason','Reference'],filtered.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('en-BD',{dateStyle:'medium',timeStyle:'short'})}</td><td><b>${esc(ctx,x.product_name)}</b><small>${esc(ctx,x.sku)}</small></td><td>${status(x.movement_type.replaceAll('_',' '),x.quantity_base<0?'warning':'good')}</td><td>${x.quantity_base>0?'+':''}${r3(x.quantity_base)} ${esc(ctx,x.base_unit)}</td><td>${x.stock_before==null?'—':`${r3(x.stock_before)} → ${r3(x.stock_after)}`}</td><td>${esc(ctx,x.reason||'—')}</td><td>${esc(ctx,x.reference_type||'—')}</td></tr>`),'No stock movements yet.')};
  $('#ssMovementSearch').oninput=draw;$('#ssMovementType').onchange=draw;draw();bindNav(ctx);if(!noWrite(ctx))document.querySelector('[data-ss-action="ss-adjust-stock"]')?.addEventListener('click',()=>stockAdjustmentModal(ctx,data.products,()=>sshopMovements(ctx)));
}
