export async function sshopReports(ctx){
  const from=dateYmd(new Date(Date.now()-29*86400000)),to=dateYmd();const reports=await ctx.api(`supershop/reports?from=${from}&to=${to}`);if(!okCurrent(ctx))return;
  page(ctx,`<section class="ss-panel"><form id="ssReportFilter" class="ss-report-filter"><label>From<input type="date" name="from" value="${from}"></label><label>To<input type="date" name="to" value="${to}"></label><button class="ss-btn ss-btn-primary">Apply range</button></form></section><div id="ssReportResults">${reportContent(ctx,reports)}</div>`);
  $('#ssReportFilter').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const r=await ctx.api(`supershop/reports?from=${encodeURIComponent(f.from)}&to=${encodeURIComponent(f.to)}`);$('#ssReportResults').innerHTML=reportContent(ctx,r)}catch(err){toastError(ctx,err)}};
}
function reportContent(ctx,r){
  const daily=r.daily||[],max=Math.max(1,...daily.map(x=>n(x.sales)));
  return `<div class="ss-kpis">${kpi(ctx,'receipt','Net sales',money(ctx,r.sales),'Invoice totals','blue')}${kpi(ctx,'chart','Gross profit',money(ctx,r.gross_profit),'Sales less weighted-average COGS','green')}${kpi(ctx,'cart','Purchases',money(ctx,r.purchases),`${r.purchase_count} receipts`,'amber')}${kpi(ctx,'package','Stock value',money(ctx,r.inventory_value),'Current aggregate inventory','cyan')}${kpi(ctx,'rotate-ccw','Returns',money(ctx,r.return_total),`${r.exchange_count} exchanges`,'violet')}${kpi(ctx,'coins','Customer due',money(ctx,r.sales_due),'Open sales balance','rose')}${kpi(ctx,'truck','Supplier due',money(ctx,r.supplier_due),`Supplier credits ${money(ctx,r.supplier_credit)}`,'amber')}${kpi(ctx,'alert-triangle','Low stock',r.low_stock_count,'Products needing attention','rose')}</div>
  <div class="ss-report-grid"><section class="ss-panel"><header class="ss-panel-head"><div><span class="ss-eyebrow">PERFORMANCE</span><h2>Daily sales</h2></div></header>${daily.length?`<div class="ss-chart">${daily.slice(-30).map(x=>`<div class="ss-chart-col" title="${x.date}: ${money(ctx,x.sales)}"><span style="height:${Math.max(4,Math.round(n(x.sales)/max*100))}%"></span><small>${String(x.date).slice(5)}</small></div>`).join('')}</div>`:empty('No sales in the selected period.')}</section>
  <section class="ss-panel"><header class="ss-panel-head"><div><span class="ss-eyebrow">PRODUCT MIX</span><h2>Category stock value</h2></div></header>${table(['Category','Products','On hand','Value','Low stock'],(r.categories||[]).map(x=>`<tr><td>${esc(ctx,x.category)}</td><td>${x.items}</td><td>${r3(x.stock)}</td><td><b>${money(ctx,x.stock_value)}</b></td><td>${x.low_stock}</td></tr>`),'No category data yet.')}</section></div>
  <section class="ss-panel"><header class="ss-panel-head"><div><span class="ss-eyebrow">BEST SELLERS</span><h2>Top products</h2></div></header>${table(['Product','SKU','Qty sold','Sales'],(r.top_products||[]).map(x=>`<tr><td><b>${esc(ctx,x.name)}</b></td><td><code>${esc(ctx,x.sku)}</code></td><td>${r3(x.quantity)}</td><td>${money(ctx,x.sales)}</td></tr>`),'No sales in the selected period.')}</section>`;
}

